124	import { createServerClient } from "@supabase/ssr";
125	import { NextResponse, type NextRequest } from "next/server";
126	
127	export async function proxy(request: NextRequest) {
128	  let response = NextResponse.next({ request });
129	  const supabase = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
130	    cookies: {
131	      getAll() { return request.cookies.getAll(); },
132	      setAll(cookiesToSet, headers) {
133	        cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
134	        response = NextResponse.next({ request });
135	        cookiesToSet.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
136	        Object.entries(headers ?? {}).forEach(([k, v]) => response.headers.set(k, v)); // no-cache headers
137	      },
138	    },
139	  });
140	  await supabase.auth.getUser(); // refresh only; NO redirect -> API routes return their own 401
141	  return response;
142	}
